    ((-moz-orient: inline) and (not (color: rgb(from red r g b)))) {
    :where(
      .roc-shadcn,
      .roc-shadcn *,
      .roc-shadcn::before,
      .roc-shadcn::after
    ) {
      --roc-sh-tw-border-style: solid;
      --roc-sh-tw-font-weight: initial;
      --roc-sh-tw-tracking: initial;
      --roc-sh-tw-shadow: 0 0 #0000;
      --roc-sh-tw-shadow-color: initial;
      --roc-sh-tw-shadow-alpha: 100%;
      --roc-sh-tw-inset-shadow: 0 0 #0000;
      --roc-sh-tw-inset-shadow-color: initial;
      --roc-sh-tw-inset-shadow-alpha: 100%;
      --roc-sh-tw-ring-color: initial;
      --roc-sh-tw-ring-shadow: 0 0 #0000;
      --roc-sh-tw-inset-ring-color: initial;
      --roc-sh-tw-inset-ring-shadow: 0 0 #0000;
      --roc-sh-tw-ring-inset: initial;
      --roc-sh-tw-ring-offset-width: 0px;
      --roc-sh-tw-ring-offset-color: #fff;
      --roc-sh-tw-ring-offset-shadow: 0 0 #0000;
    }
  }
}
/* Micro-motion: grow from the trigger, settle back on exit. */
[data-slot="context-menu-content"][data-state="open"],
[data-slot="context-menu-sub-content"][data-state="open"] {
  animation: roc-ui-pop-in var(--roc-motion-fast) var(--roc-motion-ease);
}
[data-slot="context-menu-content"][data-state="closed"],
[data-slot="context-menu-sub-content"][data-state="closed"] {
  animation: roc-ui-pop-out var(--roc-motion-quick) var(--roc-motion-ease);
}

/* Scoped preflight for copied components. No selectors affect the host page. */
@import "./ui-base.css";
:where(.roc-shadcn, .roc-shadcn *, .roc-shadcn::before, .roc-shadcn::after) {
  box-sizing: border-box;
  border-width: 0;
  border-style: solid;
  border-color: var(--roc-line, #e5e5e5);
}
:where(.roc-shadcn) {
  font-family: inherit;
  line-height: 1.5;
  color: var(--roc-ink, #252525);
  --roc-sh-color-primary: var(--roc-accent, #252525);
  --roc-sh-color-primary-foreground: #fff;
}
:where(
  button.roc-shadcn,
  input.roc-shadcn,
  select.roc-shadcn,
  textarea.roc-shadcn
) {
  font: inherit;
  color: inherit;
  background: transparent;
}
:where(button.roc-shadcn) {
  cursor: pointer;
}
:where(button.roc-shadcn:disabled) {
  cursor: not-allowed;
}
:where(
  .roc-shadcn h1,
  .roc-shadcn h2,
  .roc-shadcn h3,
  .roc-shadcn p,
  .roc-shadcn pre,
  h1.roc-shadcn,
  h2.roc-shadcn,
  h3.roc-shadcn,
  p.roc-shadcn,
  pre.roc-shadcn
) {
  margin: 0;
}
:where(ul.roc-shadcn, ol.roc-shadcn) {
  list-style: none;
  margin: 0;
  padding: 0;
}
:where(.roc-shadcn svg) {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
}
:where(.roc-shadcn input) {
  min-width: 0;
}
.roc-shadcn:focus-visible {
  outline: 2px solid var(--roc-focus, #737373);
  outline-offset: 3px;
}
@media (prefers-reduced-motion: reduce) {
  .roc-shadcn,
  .roc-shadcn * {
    scroll-behavior: auto !important;
    transition-duration: 0s !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}

.roc-shadcn[hidden],
.roc-shadcn [hidden] {
  display: none !important;
}

/* Shared ROC foundations. No global reset or host stylesheet required. */
.roc-ui {
  box-sizing: border-box;
  font: inherit;
  font-size: 13px;
  color: var(--roc-ink, #252525);
}
.roc-ui *,
.roc-ui *::before,
.roc-ui *::after {
  box-sizing: border-box;
}
.roc-ui:focus-visible {
  outline: 2px solid var(--roc-focus, #737373);
  outline-offset: 3px;
}
.roc-ui:disabled,
.roc-ui[data-disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
/* Micro-motion scale, adapted from transitions.dev. Override on `.roc-ui`. */
:where(.roc-ui, .roc-shadcn) {
  --roc-motion-quick: 150ms;
  --roc-motion-fast: 250ms;
  --roc-motion-medium: 350ms;
  --roc-motion-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --roc-motion-bounce: cubic-bezier(0.34, 1.36, 0.64, 1);
  --roc-motion-blur: 2px;
}
.roc-ui-icon,
.roc-ui > svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  pointer-events: none;
}
.roc-ui-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
/* Surfaces scale in from their anchor and settle back more quietly on exit. */
@keyframes roc-ui-pop-in {
  from {
    opacity: 0;
    transform: scale(var(--roc-pop-scale, 0.97));
  }
}
@keyframes roc-ui-pop-out {
  to {
    opacity: 0;
    transform: scale(var(--roc-pop-scale-out, 0.99));
  }
}
/* Side panels slide from their own edge; set --roc-slide-x / --roc-slide-y. */
@keyframes roc-ui-slide-in {
  from {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
@keyframes roc-ui-slide-out {
  to {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
/* A swapped icon arrives small and blurred; messages settle up from below. */
@keyframes roc-ui-icon-in {
  from {
    opacity: 0;
    scale: 0.25;
    filter: blur(var(--roc-motion-blur));
  }
}
@keyframes roc-ui-rise-in {
  from {
    opacity: 0;
    translate: 0 4px;
    filter: blur(var(--roc-motion-blur));
  }
}
/* Invalid fields answer with one short horizontal shake. */
@keyframes roc-ui-shake {
  20% {
    translate: 6px 0;
  }
  50% {
    translate: -6px 0;
  }
  78% {
    translate: 4px 0;
  }
}
@keyframes roc-ui-dismiss {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui,
  .roc-ui::before,
  .roc-ui::after {
    transition-duration: 0s !important;
    animation-duration: 0.01ms !important;
  }
}
